CREATE TABLE IF NOT EXISTS clients (id VARCHAR(36) PRIMARY KEY, name VARCHAR(180) NOT NULL, contactName VARCHAR(180) NULL, email VARCHAR(180) NULL, phone VARCHAR(80) NULL, website VARCHAR(255) NULL, notes TEXT NULL, archived TINYINT(1) NOT NULL DEFAULT 0, createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updatedAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS projects (id VARCHAR(36) PRIMARY KEY, clientId VARCHAR(36) NOT NULL, name VARCHAR(180) NOT NULL, description TEXT NULL, services JSON NOT NULL, phase VARCHAR(30) NOT NULL DEFAULT 'DISCOVERY', status VARCHAR(30) NOT NULL DEFAULT 'NOT_STARTED', priority VARCHAR(20) NOT NULL DEFAULT 'MEDIUM', startDate DATETIME NOT NULL, dueDate DATETIME NOT NULL, isExample TINYINT(1) NOT NULL DEFAULT 0, createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updatedAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX idx_project_status_due (status,dueDate), CONSTRAINT fk_project_client FOREIGN KEY (clientId) REFERENCES clients(id));
CREATE TABLE IF NOT EXISTS tasks (id VARCHAR(36) PRIMARY KEY, projectId VARCHAR(36) NOT NULL, title VARCHAR(255) NOT NULL, phase VARCHAR(30) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'TODO', dueDate DATETIME NULL, createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, completedAt DATETIME NULL, FOREIGN KEY (projectId) REFERENCES projects(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS checklistTemplates (id VARCHAR(36) PRIMARY KEY, name VARCHAR(180) NOT NULL, service VARCHAR(180) NOT NULL, createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updatedAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS checklistTemplateItems (id VARCHAR(36) PRIMARY KEY, templateId VARCHAR(36) NOT NULL, title VARCHAR(255) NOT NULL, position INT NOT NULL, FOREIGN KEY (templateId) REFERENCES checklistTemplates(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS checklistItems (id VARCHAR(36) PRIMARY KEY, projectId VARCHAR(36) NOT NULL, title VARCHAR(255) NOT NULL, phase VARCHAR(30) NOT NULL, completed TINYINT(1) NOT NULL DEFAULT 0, templateItemId VARCHAR(36) NULL, createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, completedAt DATETIME NULL, FOREIGN KEY (projectId) REFERENCES projects(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS deliverables (id VARCHAR(36) PRIMARY KEY, projectId VARCHAR(36) NOT NULL, name VARCHAR(255) NOT NULL, url VARCHAR(500) NULL, dueDate DATETIME NULL, completed TINYINT(1) NOT NULL DEFAULT 0, createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (projectId) REFERENCES projects(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS followUps (id VARCHAR(36) PRIMARY KEY, projectId VARCHAR(36) NOT NULL, title VARCHAR(255) NOT NULL, date DATETIME NOT NULL, notes TEXT NULL, completed TINYINT(1) NOT NULL DEFAULT 0, FOREIGN KEY (projectId) REFERENCES projects(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS changeRequests (id VARCHAR(36) PRIMARY KEY, projectId VARCHAR(36) NOT NULL, title VARCHAR(255) NOT NULL, description TEXT NULL, status VARCHAR(20) NOT NULL DEFAULT 'REQUESTED', createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (projectId) REFERENCES projects(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS resources (id VARCHAR(36) PRIMARY KEY, projectId VARCHAR(36) NOT NULL, type VARCHAR(50) NOT NULL, title VARCHAR(255) NOT NULL, value TEXT NULL, platform VARCHAR(100) NULL, accountIdentifier VARCHAR(180) NULL, passwordManagerUrl VARCHAR(500) NULL, FOREIGN KEY (projectId) REFERENCES projects(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS histories (id VARCHAR(36) PRIMARY KEY, projectId VARCHAR(36) NOT NULL, type VARCHAR(50) NOT NULL, description TEXT NOT NULL, date DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (projectId) REFERENCES projects(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS metrics (id VARCHAR(36) PRIMARY KEY, projectId VARCHAR(36) NOT NULL, date DATE NOT NULL, platform VARCHAR(80) NOT NULL, name VARCHAR(255) NOT NULL, investment DECIMAL(12,2) NULL, impressions INT NULL, reach INT NULL, clicks INT NULL, results INT NULL, interactions INT NULL, publications INT NULL, FOREIGN KEY (projectId) REFERENCES projects(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS payments (id VARCHAR(36) PRIMARY KEY, clientId VARCHAR(36) NULL, projectId VARCHAR(36) NULL, paymentType VARCHAR(30) NOT NULL DEFAULT 'CLIENT_INCOME', paymentDate DATE NOT NULL, amount DECIMAL(12,2) NOT NULL, concept VARCHAR(255) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'PENDING', notes TEXT NULL, confirmedAt DATETIME NULL, createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_payment_date_status (paymentDate,status), INDEX idx_payment_client (clientId), INDEX idx_payment_type (paymentType), CONSTRAINT fk_payment_client FOREIGN KEY (clientId) REFERENCES clients(id), CONSTRAINT fk_payment_project FOREIGN KEY (projectId) REFERENCES projects(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS clientRevenues (id VARCHAR(36) PRIMARY KEY, clientId VARCHAR(36) NOT NULL, revenueDate DATE NOT NULL, amount DECIMAL(12,2) NOT NULL, concept VARCHAR(255) NOT NULL, notes TEXT NULL, createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_client_revenue_date (revenueDate), INDEX idx_client_revenue_client (clientId), CONSTRAINT fk_client_revenue_client FOREIGN KEY (clientId) REFERENCES clients(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS expenses (id VARCHAR(36) PRIMARY KEY, clientId VARCHAR(36) NULL, projectId VARCHAR(36) NULL, expenseDate DATE NOT NULL, amount DECIMAL(12,2) NOT NULL, dailyAmount DECIMAL(12,2) NULL, days INT NULL, category VARCHAR(80) NOT NULL, concept VARCHAR(255) NOT NULL, notes TEXT NULL, createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_expense_date (expenseDate), INDEX idx_expense_client (clientId), INDEX idx_expense_project (projectId));
